reg=a[440:720,660:900]
lab=np.zeros(reg.shape,int); n=0
for i in range(reg.shape[0]):
  for j in range(reg.shape[1]):
    if reg[i,j] and lab[i,j]==0:
      n+=1; q=deque([(i,j)]); lab[i,j]=n
      while q:
        y,x=q.popleft()
        for dy in(-1,0,1):
          for dx in(-1,0,1):
            yy,xx=y+dy,x+dx
