import numpy as np, itertools, collections
L=open('answer.xyz').read().split('\n')
n=int(L[0]); sym=[];X=[]
for l in L[2:2+n]:
    p=l.split(); sym.append(p[0]); X.append([float(v) for v in p[1:4]])
X=np.array(X)
print('N atoms',n, collections.Counter(sym))
cov={'C':0.77,'H':0.37,'N':0.75,'O':0.73,'P':1.10,'Pd':1.39}
bonds=collections.defaultdict(list)
for i,j in itertools.combinations(range(n),2):
    r=np.linalg.norm(X[i]-X[j])
    if r < 1.3*(cov[sym[i]]+cov[sym[j]]):
        bonds[i].append(j); bonds[j].append(i)
for i in range(n):
    exp={'C':4,'H':1,'N':3,'O':2,'P':3,'Pd':5}[sym[i]]
    if len(bonds[i])!=exp: print('check',i,sym[i],len(bonds[i]),[(j,sym[j]) for j in bonds[i]])
print('rings check: Pd nbrs',[(j,sym[j]) for j in bonds[56]])
"
